/**
 * Get the number of users interested in an event
 * @param eventId The ID of the event
 * @returns The number of users interested in the event
 */
export const getEventInterestCount = async (eventId: string): Promise<number> => {
  try {
    const { count, error } = await supabase
      .from("event_attendees")
      .select("*", { count: "exact", head: true })
      .eq("event_id", eventId);
      
    if (error) {
      console.error("Error getting event interest count:", error);
      return 0;
    }
    
    return count || 0;
  } catch (error) {
    console.error("Error getting event interest count:", error);
    return 0;
  }
};

/**
 * Check if a user is interested in an event
 * @param eventId The ID of the event
 * @param userId The ID of the user
 * @returns Whether the user is interested in the event
 */
export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { data, error } = await supabase
      .from("event_attendees")
      .select("id")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle();
      
    if (error) {
      console.error("Error checking if user is interested in event:", error);
      return false;
    }
    
    return !!data;
  } catch (error) {
    console.error("Error checking if user is interested in event:", error);
    return false;
  }
};

/**
 * Check a user into an event
 * @param eventId The ID of the event
 * @param userId The ID of the user
 * @returns Whether the check-in was successful
 */
export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // First check if the user is already interested in the event
    const isInterested = await isUserInterestedInEvent(eventId, userId);
    
    if (isInterested) {
      // If already interested, update the check-in time
      const { error } = await supabase
        .from("event_attendees")
        .update({ check_in_time: new Date().toISOString() })
        .eq("event_id", eventId)
        .eq("user_id", userId);
        
      if (error) {
        console.error("Error checking in user to event:", error);
        return false;
      }
    } else {
      // If not interested, add a new record with check-in time
      const { error } = await supabase
        .from("event_attendees")
        .insert({
          event_id: eventId,
          user_id: userId,
          check_in_time: new Date().toISOString()
        });
        
      if (error) {
        console.error("Error checking in user to event:", error);
        return false;
      }
    }
    
    return true;
  } catch (error) {
    console.error("Error checking in user to event:", error);
    return false;
  }
};

/**
 * Get all attendees for an event
 * @param eventId The ID of the event
 * @param checkedInOnly Whether to only return checked-in attendees
 * @returns A list of event attendees with profile information
 */
export const getEventAttendees = async (eventId: string, checkedInOnly: boolean = false) => {
  try {
    let query = supabase
      .from("event_attendees")
      .select(`
        id,
        check_in_time,
        user_id
      `)
      .eq("event_id", eventId);
    
    if (checkedInOnly) {
      query = query.not("check_in_time", "is", null);
    }
    
    const { data: attendeesData, error: attendeesError } = await query;
    
    if (attendeesError) {
      console.error("Error fetching event attendees:", attendeesError);
      throw attendeesError;
    }
    
    if (!attendeesData || attendeesData.length === 0) {
      return [];
    }
    
    // Extract user IDs to fetch profiles
    const userIds = attendeesData.map(attendee => attendee.user_id);
    
    // Fetch user profiles in a separate query
    const { data: profilesData, error: profilesError } = await supabase
      .from("profiles")
      .select("id, name, email")
      .in("id", userIds);
    
    if (profilesError) {
      console.error("Error fetching profiles:", profilesError);
      throw profilesError;
    }
    
    // Map profiles to attendees
    return attendeesData.map(attendee => {
      const profile = profilesData?.find(profile => profile.id === attendee.user_id) || null;
      return {
        ...attendee,
        profile
      };
    });
  } catch (error) {
    console.error("Error getting event attendees:", error);
    throw error;
  }
};

